<?php require_once __DIR__.'/../classes/Database.php';require_once __DIR__.'/../classes/Session.php';Session::start();if(!Session::get('candidat_connecte')){header('Location: login.php');exit;}$pdo=(new Database())->getConnection();$id=(int)Session::get('candidat_id');$stmtVilles = $pdo->prepare(
    'SELECT id,libelle FROM ville ORDER BY libelle'
);
$stmtVilles->execute();
$villes = $stmtVilles->fetchAll();$q=$pdo->prepare('SELECT * FROM candidat WHERE id=:id');$q->execute(['id'=>$id]);$c=$q->fetch();$msg=$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if (!Session::verifyCsrf($_POST['csrf_token'] ?? null)) {
    http_response_code(403);
    exit('Requête invalide.');
} $nom=trim($_POST['nom']);$prenom=trim($_POST['prenom']);$tel=trim($_POST['telephone']);$ville=(int)$_POST['id_ville'];$st=$pdo->prepare('UPDATE candidat SET nom=:n,prenom=:p,telephone=:t,id_ville=:v WHERE id=:id');$st->execute(['n'=>$nom,'p'=>$prenom,'t'=>$tel,'v'=>$ville,'id'=>$id]);Session::set('candidat_nom',$prenom);$msg='Profil mis à jour.';if(!empty($_FILES['cv']['name'])){$f=$_FILES['cv'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['error']!==UPLOAD_ERR_OK)$err='Erreur upload.';elseif($f['size']>2097152)$err='CV supérieur à 2 Mo.';elseif($mime!=='application/pdf')$err='Le CV doit être un PDF.';else{$name='cv_'.$id.'_'.bin2hex(random_bytes(6)).'.pdf';if(move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/cv/'.$name)){$st=$pdo->prepare('UPDATE candidat SET cv_fichier=:f WHERE id=:id');$st->execute(['f'=>$name,'id'=>$id]);$msg='Profil et CV mis à jour.';}else$err='Impossible d’enregistrer le CV.';}}$q=$pdo->prepare('SELECT * FROM candidat WHERE id=:id');$q->execute(['id'=>$id]);$c=$q->fetch();}?><!doctype html><html lang="fr"><head><meta charset="UTF-8"><title>Profil</title></head><body><h1>Mon profil</h1><?php if($msg):?><p><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p><?=htmlspecialchars($err)?></p><?php endif;?><form method="post" enctype="multipart/form-data">  <input type="hidden" name="csrf_token" value="<?= htmlspecialchars(Session::csrfToken()) ?>"> <input name="nom" value="<?=htmlspecialchars($c['nom'])?>" required><input name="prenom" value="<?=htmlspecialchars($c['prenom'])?>" required><input type="email" value="<?=htmlspecialchars($c['email'])?>" disabled><input name="telephone" value="<?=htmlspecialchars($c['telephone'])?>" required><select name="id_ville" required><option value="">Ville</option><?php foreach($villes as $v):?><option value="<?= (int)$v['id'] ?>" <?=$c['id_ville']==$v['id']?'selected':''?>><?=htmlspecialchars($v['libelle'])?></option><?php endforeach;?></select><input type="file" name="cv" accept="application/pdf,.pdf"><button>Enregistrer</button></form><a href="dashboard.php">Retour</a></body></html>